mapper.select:
select * from( select A.bno ,A.btitle ,DBMS_LOB.SUBSTR(A.bcontent, 4000, 1) as bcontent ,A.id ,A.bgroup ,A.bstep ,A.bindent ,A.bhit ,A.bfile ,A.bdate ,rownum rnum ,count(*) over() as total_cnt from board A where 1=1
)
where rnum >= #{startrow} and rnum <= #{endrow}
order by bgroup desc, bstep asc

select * from board
where bno = 
(

	select prev_no from(
	select bno, lead(bno,1,-1) over(order by bgroup desc, bstep asc) prev_no from board
	)where bno = #{bno}
);

select * from board
where bno = 
(

	select next_no from(
	select bno, lag(bno,1,-1) over(order by bgroup desc, bstep asc) next_no from board
	)where bno = #{bno}
);

