,#{btitle}
,#{bcontent}

,#{id}


,#{bfile}

,board_seq.currval
,systimestamp
)

mapper.update:
update board set btitle=#{btitle}, bcontent=#{bcontent},
bfile=#{bfile},
bdate=systimestamp where bno=#{bno}

mapper.insert:
insert into board(
	bno
	,btitle
	,bcontent

	,id


	,bfile

	,bgroup
	,bstep
	,bindent
	,bdate
)
values (
	board_seq.nextval
	,#{btitle}
	,#{bcontent}

	,#{id}


	,#{bfile}

	,#{bgroup}
	,#{bstep}+1
	,#{bindent}+1
